class Solution:
    def findGoodStrings(self, n: int, s1: str, s2: str, evil: str) -> int:
        MOD = 10**9 + 7
        def nxt(cur):
            l = list(cur)
            i = n - 1
            while i >= 0 and l[i] == 'z':
                l[i] = 'a'; i -= 1
            if i < 0: return None
            l[i] = chr(ord(l[i]) + 1)
            return ''.join(l)
        cur, ans = s1, 0
        while cur is not None and cur <= s2:
            if evil not in cur:
                ans = (ans + 1) % MOD
            cur = nxt(cur)
        return ans

