class Solution {
public:
    int findGoodStrings(int n, string s1, string s2, string evil) {
        const long long MOD = 1e9 + 7;
        long long ans = 0;
        string cur = s1;
        while (true) {
            if (cur.find(evil) == string::npos)
                ans = (ans + 1) % MOD;
            if (cur == s2) break;
            int i = n - 1;
            while (i >= 0 && cur[i] == 'z') cur[i--] = 'a';
            if (i < 0) break;
            cur[i]++;
        }
        return ans;
    }
};

