class Solution {
    public int findGoodStrings(int n, String s1, String s2, String evil) {
        final long MOD = 1_000_000_007L;
        long ans = 0;
        char[] cur = s1.toCharArray();
        while (true) {
            if (!new String(cur).contains(evil)) ans = (ans + 1) % MOD;
            if (s2.equals(new String(cur))) break;
            int i = n - 1;
            while (i >= 0 && cur[i] == 'z') cur[i--] = 'a';
            if (i < 0) break;
            cur[i]++;
        }
        return (int) ans;
    }
}

