    const MOD = 1e9 + 7;
    let ans = 0, cur = s1.split('');
    const next = () => {
        let i = n - 1;
        while (i >= 0 && cur[i] === 'z') cur[i--] = 'a';
        if (i < 0) return false;
        cur[i] = String.fromCharCode(cur[i].charCodeAt(0) + 1);
        return true;
    };
    while (true) {
        if (cur.join('').indexOf(evil) === -1) ans = (ans + 1) % MOD;
        if (cur.join('') === s2 || !next()) break;
    }
    return ans;
};

