class Solution {
public:
    static constexpr long long MOD = 1e9 + 7;
    int n, m;
    string ev, bd;
    vector<int> fail;
    vector<vector<array<long long,2>>> memo;
    long long dp(int i, int j, int tight) {
        if (j == m) return 0;
        if (i == n) return 1;
        if (memo[i][j][tight] != -1) return memo[i][j][tight];
        long long total = 0;
        char hi = tight ? bd[i] : 'z';
        for (char c = 'a'; c <= hi; c++) {
            int nj = j;
            while (nj && c != ev[nj]) nj = fail[nj - 1];
            if (c == ev[nj]) nj++;
            total = (total + dp(i + 1, nj, tight && c == hi)) % MOD;
        }
        return memo[i][j][tight] = total;
    }
    long long count(const string& bound) {
        bd = bound;
        memo.assign(n, vector<array<long long,2>>(m, {-1,-1}));
        return dp(0, 0, 1);
    }
    int findGoodStrings(int N, string s1, string s2, string evil) {
        n = N; m = evil.size(); ev = evil;
        fail.assign(m, 0);
        int k = 0;
        for (int i = 1; i < m; i++) {
            while (k && evil[i] != evil[k]) k = fail[k - 1];
            if (evil[i] == evil[k]) k++;
            fail[i] = k;
        }
        long long ans = (count(s2) - count(s1) + MOD) % MOD;
        if (s1.find(evil) == string::npos) ans = (ans + 1) % MOD;
        return ans;
    }
};

