    int n, m;
    String ev, bd;
    int[] fail;
    Long[][][] memo;
    long dp(int i, int j, boolean tight) {
        if (j == m) return 0;
        if (i == n) return 1;
        if (memo[i][j][tight ? 1 : 0] != null) return memo[i][j][tight ? 1 : 0];
        long total = 0;
        char hi = tight ? bd.charAt(i) : 'z';
        for (char c = 'a'; c <= hi; c++) {
            int nj = j;
            while (nj > 0 && c != ev.charAt(nj)) nj = fail[nj - 1];
            if (c == ev.charAt(nj)) nj++;
            total = (total + dp(i + 1, nj, tight && c == hi)) % MOD;
        }
        memo[i][j][tight ? 1 : 0] = total;
        return total;
    }
    long count(String bound) {
        bd = bound;
        memo = new Long[n][m][2];
        return dp(0, 0, true);
    }
    public int findGoodStrings(int n, String s1, String s2, String evil) {
        this.n = n; this.m = evil.length(); this.ev = evil;
        fail = new int[m];
        int k = 0;
        for (int i = 1; i < m; i++) {
            while (k > 0 && evil.charAt(i) != evil.charAt(k)) k = fail[k - 1];
            if (evil.charAt(i) == evil.charAt(k)) k++;
            fail[i] = k;
        }
        long ans = ((count(s2) - count(s1)) % MOD + MOD) % MOD;
        if (s1.contains(evil) == false) ans = (ans + 1) % MOD;
        return (int) ans;
    }
}

