var findGoodStrings = function(n, s1, s2, evil) {
    const MOD = 1e9 + 7, m = evil.length;
    const fail = new Array(m).fill(0);
    let k = 0;
    for (let i = 1; i < m; i++) {
        while (k && evil[i] !== evil[k]) k = fail[k - 1];
        if (evil[i] === evil[k]) k++;
        fail[i] = k;
    }
    const count = (bound) => {
        const memo = Array.from({length: n}, () => Array.from({length: m}, () => [null, null]));
        const dp = (i, j, tight) => {
            if (j === m) return 0;
            if (i === n) return 1;
            const t = tight ? 1 : 0;
            if (memo[i][j][t] !== null) return memo[i][j][t];
            let total = 0;
            const hi = tight ? bound.charCodeAt(i) : 122;
            for (let c = 97; c <= hi; c++) {
                const ch = String.fromCharCode(c);
                let nj = j;
                while (nj && ch !== evil[nj]) nj = fail[nj - 1];
                if (ch === evil[nj]) nj++;
                total = (total + dp(i + 1, nj, tight && c === hi)) % MOD;
            }
            return memo[i][j][t] = total;
        };
        return dp(0, 0, true);
    };
    let ans = ((count(s2) - count(s1)) % MOD + MOD) % MOD;
    if (s1.indexOf(evil) === -1) ans = (ans + 1) % MOD;
